package xyz.shuncongci.leica

import org.junit.Assert.*
import org.junit.Test
import kotlin.math.*
import kotlin.random.Random
import xyz.shuncongci.leica.CompositionGeometry.Crop

class CompositionTileMotionTest {
    private val options=listOf(CompositionGeometry.FULL,Crop(.07,.19,.81,.88),Crop(.21,.03,.97,.73),Crop(.13,.11,.91,.94))
    private fun ready(w:Int=4031,h:Int=3023)=CompositionTileMotion(w,h).apply{beginAnalysis();advance(1200f);reveal(options);advance(650f)}
    private fun area(b:NativeImageMath.Box)=b.w.toLong()*b.h
    private fun coverage(s:CompositionTileMotion,index:Int){
        val box=CompositionGeometry.pixels(s.mesh.crops[index],s.mesh.width,s.mesh.height)
        val kept=s.mesh.pieces.filter{CompositionTileMath.kept(it,box)}
        assertEquals(area(box),kept.sumOf{area(it.box)})
    }
    @Test fun meshCoversWholeOddSizedPhotoExactly(){val m=CompositionTileMath.mesh(4031,3023,options);assertEquals(4031L*3023,m.pieces.sumOf{area(it.box)})}
    @Test fun everyProposalHasExactSourcePixelArea(){val s=ready();options.indices.forEach{coverage(s,it)}}
    @Test fun boundaryPiecesNeverStraddleAnyProposal(){val s=ready();for(c in s.mesh.crops){val b=CompositionGeometry.pixels(c,s.mesh.width,s.mesh.height);for(p in s.mesh.pieces){val q=p.box;val intersection=max(0,min(q.right,b.right)-max(q.left,b.left)).toLong()*max(0,min(q.bottom,b.bottom)-max(q.top,b.top));assertTrue(intersection==0L || intersection==area(q))}}}
    @Test fun meshHasHundredsOfPiecesButIsBounded(){for((w,h) in listOf(4000 to 3000,3000 to 4000,4000 to 4000)){val m=CompositionTileMath.mesh(w,h,options);assertTrue(m.pieces.size in 300..900)}}
    @Test fun thinAndTinyImagesHaveNoZeroAreaPieces(){for((w,h) in listOf(1 to 1,1 to 5000,5000 to 1,2 to 3,17 to 9)){val m=CompositionTileMath.mesh(w,h,options);assertTrue(m.pieces.all{it.box.w>0 && it.box.h>0});assertEquals(w.toLong()*h,m.pieces.sumOf{area(it.box)})}}
    @Test fun smallMeshHasNoOverlapsOrGaps(){val m=CompositionTileMath.mesh(71,53,options);val hits=IntArray(71*53);for(p in m.pieces)for(y in p.box.top until p.box.bottom)for(x in p.box.left until p.box.right)hits[y*71+x]++;assertTrue(hits.all{it==1})}
    @Test fun randomProposalCutsPreserveExactArea(){val r=Random(812);repeat(100){val w=r.nextInt(1,12001);val h=r.nextInt(1,12001);val crops=List(4){CompositionGeometry.placed(.1+r.nextDouble()*.9,.1+r.nextDouble()*.9,r.nextDouble(),r.nextDouble())};val m=CompositionTileMath.mesh(w,h,crops);for(c in crops){val box=CompositionGeometry.pixels(c,w,h);assertEquals(area(box),m.pieces.filter{CompositionTileMath.kept(it,box)}.sumOf{area(it.box)})}}}
    @Test fun animationPiecesKeepIdentityAcrossAllChoices(){val s=ready();val pieces=s.mesh.pieces;options.indices.forEach{s.select(it);s.advance(1450f);assertSame(pieces,s.mesh.pieces)}}
    @Test fun splitPiecesShareTheirParentDepthWave(){val m=CompositionTileMath.mesh(4031,3023,options);val groups=m.pieces.groupBy{it.parent};assertTrue(groups.values.any{it.size>1});groups.values.forEach{g->assertEquals(1,g.map{CompositionTileMath.wave(it.parent,1.4f)}.toSet().size)}}
    @Test fun loadingStartsFlatThenSeparates(){val s=CompositionTileMotion(4000,3000);s.beginAnalysis();assertEquals(0f,s.camera.lift,0f);s.advance(700f);assertEquals(1f,s.camera.lift,0f);assertTrue(s.canOrbit);assertTrue(s.camera.yaw>.4f)}
    @Test fun loadingTilesActuallyMoveForwardAndBackward(){val a=(0..100).map{CompositionTileMath.wave(it,1f)};val b=(0..100).map{CompositionTileMath.wave(it,2f)};assertTrue(a.min()<0);assertTrue(a.max()>0);assertNotEquals(a,b)}
    @Test fun draggingChangesOnlyViewNotCropOrOutput(){val s=CompositionTileMotion(4000,3000);s.beginAnalysis();s.advance(700f);val old=s.camera;val plan=CompositionOutput.plan(4000,3000,s.crop,BokehOutput.SIZE_2048);s.drag(.2f,.1f);assertNotEquals(old.yaw,s.camera.yaw);assertEquals(plan,CompositionOutput.plan(4000,3000,s.crop,BokehOutput.SIZE_2048));assertTrue(s.departures.all{it==0f})}
    @Test fun proposalsFinishByReturningTo2D(){val s=CompositionTileMotion(4000,3000);s.beginAnalysis();s.advance(1200f);s.reveal(options);assertEquals(CompositionTileMotion.Mode.REVEALING,s.mode);s.advance(650f);assertEquals(CompositionTileMotion.Camera(),s.camera);assertFalse(s.needsFrames)}
    @Test fun selectionStays2DWhilePiecesFly(){val s=ready();s.select(1);s.advance(250f);assertEquals(0f,s.camera.lift,0f);assertEquals(0f,s.camera.yaw,0f);assertEquals(0f,s.camera.pitch,0f);assertFalse(s.canOrbit);assertTrue(s.departures.any{it>0f});val q=FloatArray(10);for(i in s.mesh.pieces.indices){s.project(i,720,900,q);assertEquals(0f,q[8],0f);assertEquals(q[0]+q[4],q[2]+q[6],.0003f);assertEquals(q[1]+q[5],q[3]+q[7],.0003f)}}
    @Test fun outgoingPiecesFlyTogetherWithoutStagger(){val s=ready();s.select(1);s.advance(680f);val box=CompositionGeometry.pixels(s.crop,s.mesh.width,s.mesh.height);val departing=s.departures.indices.filter{!CompositionTileMath.kept(s.mesh.pieces[it],box)};assertTrue(departing.isNotEmpty());val first=s.departures[departing.first()];assertTrue(first>0 && first<1);departing.forEach{assertEquals(first,s.departures[it],0f)}}
    @Test fun keptPiecesRemainPresentDuringFlight(){val s=ready();s.select(1);s.advance(680f);val box=CompositionGeometry.pixels(s.crop,s.mesh.width,s.mesh.height);s.departures.indices.filter{CompositionTileMath.kept(s.mesh.pieces[it],box)}.forEach{assertEquals(0f,s.departures[it],0f)}}
    @Test fun selectionEndsFlatWithExactChosenMask(){val s=ready();s.select(1);s.advance(1450f);assertEquals(CompositionTileMotion.Mode.READY,s.mode);assertEquals(CompositionTileMotion.Camera(crop=s.crop),s.camera);val box=CompositionGeometry.pixels(s.crop,s.mesh.width,s.mesh.height);s.mesh.pieces.forEachIndexed{i,p->assertEquals(if(CompositionTileMath.kept(p,box))0f else 1f,s.departures[i],0f)}}
    @Test fun returningAndLeavingPiecesMoveInSamePhase(){val s=ready();s.select(1);s.settle();val old=s.departures.copyOf();s.select(2);s.advance(680f);val b=CompositionGeometry.pixels(s.crop,s.mesh.width,s.mesh.height);val back=old.indices.filter{old[it]==1f && CompositionTileMath.kept(s.mesh.pieces[it],b)};val out=old.indices.filter{old[it]==0f && !CompositionTileMath.kept(s.mesh.pieces[it],b)};assertTrue(back.isNotEmpty() && out.isNotEmpty());val f=s.departures[out.first()];back.forEach{assertEquals(1-f,s.departures[it],.000001f)};out.forEach{assertEquals(f,s.departures[it],0f)}}
    @Test fun keptByBothProposalsNeverDisappears(){val s=ready();s.select(1);s.settle();val old=s.departures.copyOf();s.select(2);s.advance(680f);val b=CompositionGeometry.pixels(s.crop,s.mesh.width,s.mesh.height);old.indices.filter{old[it]==0f && CompositionTileMath.kept(s.mesh.pieces[it],b)}.forEach{assertEquals(0f,s.departures[it],0f)}}
    @Test fun restoringFullPhotoBringsEveryPieceBack(){val s=ready();s.select(1);s.settle();s.select(0);s.advance(680f);assertTrue(s.departures.any{it>0 && it<1});s.advance(1000f);assertTrue(s.departures.all{it==0f});assertEquals(CompositionGeometry.FULL,s.crop)}
    @Test fun rapidRetargetStartsAtExactlyCurrentProjectedFrame(){val s=ready();s.select(1);s.advance(680f);val before=Array(s.mesh.pieces.size){FloatArray(10).also{a->s.project(it,720,900,a)}};val camera=s.camera;val deps=s.departures.copyOf();s.select(2);s.advance(0f);assertEquals(camera,s.camera);assertArrayEquals(deps,s.departures,0f);before.forEachIndexed{i,a->val after=FloatArray(10);s.project(i,720,900,after);assertArrayEquals(a,after,.00001f)}}
    @Test fun latestChoiceWinsWithoutQueuedReplays(){val s=ready();repeat(70){s.select(1+it%3);s.advance(40f)};s.select(2);s.advance(1450f);assertEquals(2,s.selected);assertFalse(s.needsFrames);val camera=s.camera;s.advance(100000f);assertEquals(camera,s.camera)}
    @Test fun settlingForReducedMotionOrBackgroundIsImmediate(){val s=ready();s.select(1);s.advance(430f);s.settle();assertFalse(s.needsFrames);assertEquals(0f,s.camera.lift,0f);assertTrue(s.departures.all{it==0f || it==1f})}
    @Test fun cancellingAnalysisSettlesFullPhoto(){val s=CompositionTileMotion(3000,4000);s.beginAnalysis();s.advance(1000f);s.settle();assertEquals(CompositionGeometry.FULL,s.crop);assertTrue(s.departures.all{it==0f});assertFalse(s.needsFrames)}
    @Test fun rotationIsBoundedAndProjectionFinite(){val s=ready();s.select(1);s.advance(600f);s.drag(100000f,-100000f);assertTrue(abs(s.camera.yaw)<=.850001f);assertTrue(abs(s.camera.pitch)<=.550001f);val a=FloatArray(10);for(i in s.mesh.pieces.indices){s.project(i,1920,1080,a);assertTrue(a.all{it.isFinite()});assertTrue(a[9] in 0f..1f)}}
    @Test fun projectionFiniteAcrossSizesAndAllMotionStages(){val a=FloatArray(10);for((w,h) in listOf(4000 to 3000,3000 to 4000,50 to 5000)){val s=ready(w,h);for(choice in 0..3){s.select(choice);repeat(29){s.advance(50f);for(i in s.mesh.pieces.indices){s.project(i,320,460,a);assertTrue(a.all{it.isFinite()});assertTrue(a[8]<3.8f)}}}}}
    @Test fun settledProjectionMatchesFlatCropMapping(){val s=ready();s.select(1);s.settle();val c=s.crop;val scale=min(720/(s.mesh.width*c.w),900/(s.mesh.height*c.h))*.94;val left=(720-s.mesh.width*c.w*scale)/2;val top=(900-s.mesh.height*c.h*scale)/2;val a=FloatArray(10);for((i,p) in s.mesh.pieces.withIndex()){s.project(i,720,900,a);if(a[9]==0f)continue;assertEquals(left+(p.box.left-c.l*s.mesh.width)*scale,a[0].toDouble(),.0003);assertEquals(top+(p.box.top-c.t*s.mesh.height)*scale,a[1].toDouble(),.0003);assertEquals(1f,a[9],0f)}}
    @Test fun oneStepAndManyFramesConvergeToSameResult(){val a=ready();val b=ready();a.select(1);b.select(1);a.advance(725f);repeat(25){b.advance(29f)};assertEquals(a.camera,b.camera);assertArrayEquals(a.departures,b.departures,0f)}
    @Test fun animationNeverChangesExportRecipe(){val s=ready();val plans=options.map{CompositionOutput.plan(4031,3023,it,BokehOutput.SIZE_2048)};for(i in 0..3){s.select(i);repeat(20){s.advance(40f)}};assertEquals(plans,options.map{CompositionOutput.plan(4031,3023,it,BokehOutput.SIZE_2048)})}
    @Test fun sameChoiceDoesNotRestartTransition(){val s=ready();s.select(1);s.advance(650f);val camera=s.camera;s.select(1);assertEquals(camera,s.camera);s.advance(800f);assertFalse(s.needsFrames)}
    @Test(expected=IllegalArgumentException::class) fun nanTimeRejected(){ready().advance(Float.NaN)}
    @Test(expected=IllegalArgumentException::class) fun negativeTimeRejected(){ready().advance(-1f)}
    @Test(expected=IllegalArgumentException::class) fun invalidChoiceRejected(){ready().select(9)}
    @Test(expected=IllegalArgumentException::class) fun tooManyProposalsRejected(){CompositionTileMath.mesh(100,100,List(5){CompositionGeometry.FULL})}
}
